    first_name = friend.get('first_name', '')
    last_name = friend.get('last_name', '')
    email = friend.get('email', '')
    if email in friend_shares and email:
        received_requests = []
        page_index = 0
        while True:
            page = apis.venmo.show_received_payment_requests(access_token=venmo_token, query=email, status='approved', page_index=page_index, page_limit=20)
